// Supplemental UI-only adapter. Not an authentication, persistence or backup proof.
import {createRoot} from 'react-dom/client';
import {ExpenseEditor} from '../../src/app/expenses/expense-editor';
import type {createExpenseClient,ExpenseContext} from '../../src/client/expenses';
import type {ExpenseRevision} from '../../src/bookkeeping/expenses/expense-contract';
import type {createReceiptClient} from '../../src/client/expense-receipts';
import type {ReceiptView} from '../../src/bookkeeping/expenses/receipt-contract';
const businessId='11111111-1111-1111-1111-111111111111',epoch='22222222-2222-2222-2222-222222222222',actorId='33333333-3333-3333-3333-333333333333';
const rows:ExpenseRevision[]=[];let loseReply=true;
const context:ExpenseContext={businessId,recoveryEpoch:epoch,writeState:'ready',binding:'synthetic-layout-only'};
const client:ReturnType<typeof createExpenseClient>={async context(){return context;},async history(){return rows;},async save(_context,request){let row=rows.find(r=>r.operationId===request.operationId);if(!row){row={businessId,expenseId:request.expenseId,revision:(BigInt(request.expectedRevision)+1n).toString(),operationId:request.operationId,actorId,recordedAt:'2026-10-28T23:00:00.000000Z',payload:request.payload};rows.push(row);}if(loseReply){loseReply=false;throw new Error('Synthetic lost response');}return {state:'committed',expense:row};}};
const receipts:ReceiptView[]=[];let loseReceiptReply=true,loseResumeReply=true;
const receiptClient:ReturnType<typeof createReceiptClient>={async list(_context,expenseId){if(!receipts.some(r=>r.receiptId==='aaaaaaaa-aaaa-aaaa-aaaa-aaaaaaaaaaaa'))receipts.push({receiptId:'aaaaaaaa-aaaa-aaaa-aaaa-aaaaaaaaaaaa',expenseId,expenseRevision:'1',receiptVersion:'1',status:'reserved',declaredType:'image/png',byteSize:4,sourceSha256:null});return receipts;},async attach(attempt){let receipt=receipts.find(r=>r.receiptId===attempt.receiptId);if(!receipt){receipt={receiptId:attempt.receiptId,expenseId:attempt.expenseId,expenseRevision:attempt.expenseRevision,receiptVersion:'2',status:'available',declaredType:'image/png',byteSize:attempt.file.size,sourceSha256:'a'.repeat(64)};receipts.push(receipt);}if(loseReceiptReply){loseReceiptReply=false;throw new Error('Synthetic lost receipt reply');}return receipt;},async resume(_context,r){const saved={...r,receiptVersion:'2' as const,status:'available' as const,sourceSha256:'a'.repeat(64)},index=receipts.findIndex(row=>row.receiptId===r.receiptId);if(index<0)throw new Error();receipts[index]=saved;if(loseResumeReply){loseResumeReply=false;throw new Error('Synthetic lost resume reply');}return saved;},async download(_context,r,variant){return {blob:new Blob(['Synthetic UI-only receipt download'],{type:'image/png'}),name:`receipt-${r.receiptId}${variant==='preview'?'-preview':''}.png`};}};
createRoot(document.getElementById('root')!).render(<main><ExpenseEditor client={client} receiptClient={receiptClient}/></main>);
